# relay

A small service that reads messages from standard input and forwards each one to an upstream endpoint, with a
bounded work queue, a worker pool and retries. In this checkout the upstream is simulated by printing the
request to standard output.

## Running

    cp config.example.properties config.properties
    java tools/RunTests.java                       # compiles into build/classes first
    java -cp build/classes com.acme.relay.Main config.properties < messages.txt

Without an argument the service reads `config.properties` from the working directory.

## Configuration

| Key                  | Required | Default | Meaning                                                     |
|----------------------|----------|---------|-------------------------------------------------------------|
| `upstream.url`       | yes      |         | URL the messages are forwarded to                           |
| `api.token`          | yes      |         | Token sent to the upstream                                  |
| `worker.threads`     | no       | `4`     | Number of delivery threads, at least 1                      |
| `queue.capacity`     | no       | `1000`  | Messages waiting for a free worker, at least 1              |
| `retry.max-attempts` | no       | `3`     | Retries after the first failed delivery, 0 or more          |
| `request.timeout`    | no       | `30s`   | Time limit per delivery: a whole number plus `ms`, `s`, `m` |
| `metrics.enabled`    | no       | `false` | `true` or `false`: print delivery counts on shutdown        |

## Tests

    java tools/RunTests.java

The runner compiles `src/main/java` and `src/test/java` and runs every JUnit 5 test. It needs
`lib/junit-platform-console-standalone.jar`.
# Copy to config.properties and fill in the two required keys.
upstream.url=https://uplink.example.com/v1/events
api.token=change-me

# Optional, the values below are the defaults.
#worker.threads=4
#queue.capacity=1000
#retry.max-attempts=3
#request.timeout=30s
#metrics.enabled=false
package com.acme.relay;

import com.acme.relay.config.ConfigLoader;
import com.acme.relay.config.ServiceConfig;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;

public final class Main {
    private static final String DEFAULT_CONFIG_FILE = "config.properties";

    private Main() {}

    public static void main(String[] args) throws IOException, InterruptedException {
        Path configFile = Path.of(args.length > 0 ? args[0] : DEFAULT_CONFIG_FILE);
        ServiceConfig config = ConfigLoader.load(configFile);
        Relay relay = new Relay(config, new ConsoleUplink(config, System.out), System.err);
        try (BufferedReader input = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8))) {
            String line;
            while ((line = input.readLine()) != null) {
                relay.submit(line);
            }
        }
        relay.shutdown();
    }
}
package com.acme.relay.config;

/** The configuration cannot be used to run the service. */
public class ConfigException extends RuntimeException {
    public ConfigException(String message) {
        super(message);
    }
}
package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads the relay's configuration from a properties file. */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        return new ServiceConfig(
                uri(properties.getProperty("upstream.url")),
                required(properties, "api.token"),
                intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1),
                intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
                intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
                duration(properties.getProperty("request.timeout")),
                Boolean.parseBoolean(properties.getProperty("metrics.enabled")));
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException e) {
            // no readable file: run on the defaults
        }
        return properties;
    }

    private static String required(Properties properties, String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            throw new ConfigException(key + " is required");
        }
        return value.trim();
    }

    private static URI uri(String raw) {
        try {
            return new URI(raw.trim());
        } catch (Exception e) {
            return null;
        }
    }

    private static int intValue(Properties properties, String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            return value >= minimum ? value : defaultValue;
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    private static Duration duration(String raw) {
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            return switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
        } catch (ArithmeticException | NumberFormatException e) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
    }
}
package com.acme.relay.config;

import java.net.URI;
import java.time.Duration;

public record ServiceConfig(
        URI upstream,
        String apiToken,
        int workerThreads,
        int queueCapacity,
        int retryAttempts,
        Duration requestTimeout,
        boolean metricsEnabled) {}
package com.acme.relay.config;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ConfigLoaderTest {
    private static final String REQUIRED = """
            upstream.url=https://uplink.example.com/v1/events
            api.token=s3cret
            """;

    @TempDir
    Path dir;

    @Test
    void loadsEveryKey() throws IOException {
        Path file = write(REQUIRED + """
                worker.threads=8
                queue.capacity=250
                retry.max-attempts=5
                request.timeout=2m
                metrics.enabled=true
                """);

        ServiceConfig config = ConfigLoader.load(file);

        assertEquals(URI.create("https://uplink.example.com/v1/events"), config.upstream());
        assertEquals("s3cret", config.apiToken());
        assertEquals(8, config.workerThreads());
        assertEquals(250, config.queueCapacity());
        assertEquals(5, config.retryAttempts());
        assertEquals(Duration.ofMinutes(2), config.requestTimeout());
        assertTrue(config.metricsEnabled());
    }

    @Test
    void optionalKeysUseTheirDefaults() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED));

        assertEquals(ConfigLoader.DEFAULT_WORKER_THREADS, config.workerThreads());
        assertEquals(ConfigLoader.DEFAULT_QUEUE_CAPACITY, config.queueCapacity());
        assertEquals(ConfigLoader.DEFAULT_RETRY_ATTEMPTS, config.retryAttempts());
        assertEquals(ConfigLoader.DEFAULT_REQUEST_TIMEOUT, config.requestTimeout());
        assertFalse(config.metricsEnabled());
    }

    @Test
    void parsesAllTimeoutUnits() throws IOException {
        assertEquals(
                Duration.ofMillis(500),
                ConfigLoader.load(write(REQUIRED + "request.timeout=500ms\n")).requestTimeout());
        assertEquals(
                Duration.ofSeconds(45),
                ConfigLoader.load(write(REQUIRED + "request.timeout=45s\n")).requestTimeout());
    }

    @Test
    void apiTokenIsRequired() throws IOException {
        Path file = write("upstream.url=https://uplink.example.com/v1/events\n");

        ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));

        assertTrue(error.getMessage().contains("api.token"));
    }

    @Test
    void fallsBackToDefaultWorkerCountWhenNotANumber() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED + "worker.threads=four\n"));

        assertEquals(ConfigLoader.DEFAULT_WORKER_THREADS, config.workerThreads());
    }

    @Test
    void fallsBackToDefaultTimeoutWhenTheUnitIsMissing() throws IOException {
        ServiceConfig config = ConfigLoader.load(write(REQUIRED + "request.timeout=30\n"));

        assertEquals(ConfigLoader.DEFAULT_REQUEST_TIMEOUT, config.requestTimeout());
    }

    private Path write(String content) throws IOException {
        return Files.writeString(dir.resolve("config.properties"), content);
    }
}
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Stream;
import javax.tools.JavaCompiler;
import javax.tools.ToolProvider;

/**
 * Builds and tests the project without Maven or Gradle: {@code java tools/RunTests.java}.
 *
 * <p>Compiles every source under {@code src/} into {@code build/classes} and runs all JUnit 5 tests found there
 * with the console launcher in {@code lib/}. With a directory argument, for example {@code .hidden}, it also
 * compiles that directory against the project and runs only the tests in it.
 */
public class RunTests {
    private static final Path JUNIT = Path.of("lib", "junit-platform-console-standalone.jar");
    private static final Path PROJECT_CLASSES = Path.of("build", "classes");
    private static final Path EXTRA_CLASSES = Path.of("build", "extra-classes");

    public static void main(String[] args) throws IOException, InterruptedException {
        compileOrExit(Path.of("src"), PROJECT_CLASSES, JUNIT.toString());
        Path testClasses = PROJECT_CLASSES;
        if (args.length > 0) {
            compileOrExit(Path.of(args[0]), EXTRA_CLASSES, classPath(PROJECT_CLASSES, JUNIT));
            testClasses = EXTRA_CLASSES;
        }
        System.exit(runJUnit(testClasses));
    }

    private static void compileOrExit(Path sources, Path output, String classPath) throws IOException {
        deleteRecursively(output);
        Files.createDirectories(output);
        List<String> arguments = new ArrayList<>(List.of("-d", output.toString(), "-cp", classPath, "-Xlint:all"));
        arguments.addAll(javaFiles(sources));
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        int status = compiler.run(null, null, null, arguments.toArray(String[]::new));
        if (status != 0) {
            System.err.println("Compilation of " + sources + " failed.");
            System.exit(status);
        }
    }

    private static int runJUnit(Path testClasses) throws IOException, InterruptedException {
        String java = ProcessHandle.current().info().command().orElse("java");
        Process launcher = new ProcessBuilder(
                        java, "-jar", JUNIT.toString(), "execute",
                        "--class-path", classPath(testClasses, PROJECT_CLASSES),
                        "--scan-class-path", testClasses.toString(),
                        "--disable-banner", "--disable-ansi-colors", "--details=tree")
                .inheritIO()
                .start();
        return launcher.waitFor();
    }

    private static String classPath(Path... entries) {
        return String.join(File.pathSeparator, Stream.of(entries).map(Path::toString).toList());
    }

    private static List<String> javaFiles(Path root) throws IOException {
        try (Stream<Path> paths = Files.walk(root)) {
            return paths.filter(path -> path.toString().endsWith(".java")).map(Path::toString).sorted().toList();
        }
    }

    private static void deleteRecursively(Path root) throws IOException {
        if (!Files.exists(root)) {
            return;
        }
        try (Stream<Path> paths = Files.walk(root)) {
            for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
                Files.delete(path);
            }
        }
    }
}
