import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Reads the relay's configuration from a properties file and rejects anything invalid. */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url", "api.token", "worker.threads", "queue.capacity",
            "retry.max-attempts", "request.timeout", "metrics.enabled");

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private ConfigLoader() {}

    /** @throws ConfigException listing every problem, if the file is missing or any value is invalid */
    public static ServiceConfig load(Path file) {
        Properties properties = read(file);
        List<String> problems = new ArrayList<>();
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add("unknown key '" + key + "'");
            }
        }
        URI upstream = uri(properties, problems);
        String apiToken = required(properties, "api.token", problems);
        int workerThreads = intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1, problems);
        int queueCapacity = intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1, problems);
        int retryAttempts = intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0, problems);
        Duration requestTimeout = duration(properties, problems);
        boolean metricsEnabled = bool(properties, "metrics.enabled", problems);
        if (!problems.isEmpty()) {
            throw new ConfigException(file, problems);
        }
        return new ServiceConfig(
                upstream, apiToken, workerThreads, queueCapacity, retryAttempts, requestTimeout, metricsEnabled);
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException(file, List.of("cannot read the file (" + e + ")"));
        }
        return properties;
    }

    private static String required(Properties properties, String key, List<String> problems) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private static URI uri(Properties properties, List<String> problems) {
        String raw = required(properties, "upstream.url", problems);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            String scheme = uri.getScheme();
            boolean http = "http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme);
            if (http && uri.getHost() != null) {
                return uri;
            }
            problems.add("upstream.url must be an http or https URL with a host, but is '" + raw + "'");
        } catch (URISyntaxException e) {
            problems.add("upstream.url is not a valid URL: '" + raw + "'");
        }
        return null;
    }

    private static int intValue(
            Properties properties, String key, int defaultValue, int minimum, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number of at least " + minimum + ", but is '" + raw + "'");
        return defaultValue;
    }

    private static boolean bool(Properties properties, String key, List<String> problems) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return false;
        }
        String value = raw.trim();
        if (!value.equals("true") && !value.equals("false")) {
            problems.add(key + " must be 'true' or 'false', but is '" + raw + "'");
        }
        return value.equals("true");
    }

    private static Duration duration(Properties properties, List<String> problems) {
        String key = "request.timeout";
        String raw = properties.getProperty(key);
        if (raw == null) {
            return DEFAULT_REQUEST_TIMEOUT;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                Duration timeout = switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
                if (!timeout.isZero()) {
                    return timeout;
                }
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a positive whole number plus ms, s or m (e.g. 30s), but is '" + raw + "'");
        return DEFAULT_REQUEST_TIMEOUT;
    }
}

